{
  "hypothesis": "Replacing one-pass random cut sampling with coarse-to-fine refinement around promising cuts will locate a better packet-order transition and yield a verified gain of at least 1e-5 after weight repair.",
  "rationale": "The parent spends its topology budget testing unrelated cuts, although small changes to a cut can move an entire packet across a reflection boundary. This version retains the same transformations and weight repair but reserves most of the topology-search time for multiscale refinement, including snapping proposed cuts to nearby support boundaries.",
  "source": "import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'coarse_fraction': (0.16, 0.05, 0.30),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'cuts': (36, 12, 120),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    coarse_end = start + float(params['coarse_fraction']) * budget_s
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf
    tested = {}
    leaders = [[], [], []]

    def approximate(f):
        sp = fft.rfft(f, m)
        c = fft.irfft(sp*sp, m)[:2*n-1]
        return float((2*np.dot(c, c) + np.dot(c[:-1], c[1:])) /
                     (3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        k = int(k)
        if not 0 < k < n or time.monotonic() >= search_end:
            return None
        key = (k, mode)
        if key in tested:
            return tested[key]
        f = make(k, mode)
        score = approximate(f)
        tested[key] = score
        leaders[mode].append((score, k))
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline - 1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        return score

    occupied = f0 > 0
    boundaries = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, boundaries, n]
    widths = np.diff(edges)
    cuts = set()
    cumulative = np.cumsum(f0)
    for q in np.linspace(0.01, 0.99, int(params['cuts'])):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(np.searchsorted(cumulative, q*cumulative[-1])))
    for d in np.geomspace(1, max(2, n//3), 18):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(d))
        cuts.add(n-int(d))
    for j in np.argsort(widths)[::-1][:24]:
        if time.monotonic() >= coarse_end:
            break
        if not occupied[edges[j]]:
            cuts.update((int(edges[j]), int(edges[j+1]), int((edges[j]+edges[j+1])//2)))
    jobs = [(k, mode) for k in sorted(cuts) if 0 < k < n for mode in (0, 1, 2)]
    rng.shuffle(jobs)
    for k, mode in jobs:
        if time.monotonic() >= coarse_end:
            break
        inspect(k, mode)

    # Refine the best distinct basins at each scale instead of spending the
    # remaining topology budget on unrelated random cuts.
    radius = max(1, n//32)
    while time.monotonic() < search_end:
        proposals = []
        for mode in range(3):
            if time.monotonic() >= search_end:
                break
            ranked = sorted(leaders[mode], reverse=True)
            centers = []
            for score, k in ranked:
                if time.monotonic() >= search_end:
                    break
                if all(abs(k-j) > max(1, radius//2) for j in centers):
                    centers.append(k)
                if len(centers) == 3:
                    break
            for k in centers:
                if time.monotonic() >= search_end:
                    break
                for offset in (-radius, radius, -max(1, radius//3), max(1, radius//3)):
                    if time.monotonic() >= search_end:
                        break
                    target = k + offset
                    proposals.append((target, mode))
                    if len(boundaries):
                        j = int(np.searchsorted(boundaries, target))
                        if j < len(boundaries):
                            proposals.append((int(boundaries[j]), mode))
                        if j:
                            proposals.append((int(boundaries[j-1]), mode))
        fresh = 0
        # Interleave modes and basins so one reflection cannot consume a level.
        rng.shuffle(proposals)
        for k, mode in proposals:
            if time.monotonic() >= search_end:
                break
            if 0 < k < n and (k, mode) not in tested:
                fresh += 1
                inspect(k, mode)
        if radius == 1:
            if fresh == 0:
                break
        else:
            radius = max(1, radius//3)

    if contender is None or contender_score < baseline - float(params['repair_tolerance']):
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
    if time.monotonic() >= deadline - 1.5:
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    base = contender
    spec = fft.rfft(base, m)
    peak = fft.irfft(spec*spec, m)[:2*n-1].max()
    base = base / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]
    beta = float(params['beta'])

    class Stop(Exception):
        pass

    def materialize(x):
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        return f

    def objective(x):
        nonlocal best_score, best_f
        if time.monotonic() >= deadline-1.5:
            raise Stop()
        f = materialize(x)
        sp = fft.rfft(f, m)
        c = fft.irfft(sp*sp, m)[:2*n-1]
        peak = c.max()
        e = np.exp(beta*(c-peak))
        z = e.sum()
        smooth = peak + np.log(z)/beta
        num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
        total = f.sum()
        quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
        if quick > best_score + 1e-13 and time.monotonic() < deadline-1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        g = 4*c
        g[1:] += c[:-1]
        g[:-1] += c[1:]
        g /= 3*num
        g -= e/(z*smooth)
        corr = fft.irfft(fft.rfft(g,m)*np.conj(sp),m)[:n]
        local = (2*corr[indices]-2/total)*active
        grad = 2*x*np.bincount(labels,weights=local,minlength=groups)
        value = np.log(num)-2*np.log(total)-np.log(smooth)
        return -value, -grad

    try:
        minimize(objective, np.ones(groups), jac=True, method='L-BFGS-B',
                 options={'maxcor': 7, 'maxiter': 10000, 'maxfun': 20000,
                          'ftol': 0.0, 'gtol': 0.0, 'maxls': 15})
    except Stop:
        pass
    if best_f is None:
        return init
    return {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
